let cursor = 0, failures = [], run_id = "nightly-98";
while (true) {
  const r = await tools.ci_list_failures(cursor === 0 ? { run_id } : { run_id, cursor });
  failures.push(...r.failures);
  if (r.next_cursor === null || r.next_cursor === undefined) break;
  cursor = r.next_cursor;
}
store("failures", failures);
console.log(failures.length);
console.log(JSON.stringify(failures[0]));

const failures = load("failures");
const results = {};
const limit = 16;
let i = 0;
async function worker() {
  while (i < failures.length) {
    const f = failures[i++];
    for (let attempt = 0; attempt < 3; attempt++) {
      try { const r = await tools.ci_get_failure_history({ failure_id: f.id }); results[f.id] = r.history; break; }
      catch (e) { if (attempt === 2) results[f.id] = { error: String(e) }; }
    }
  }
}
await Promise.all(Array.from({length: limit}, worker));
store("hist", results);
const bad = Object.entries(results).filter(([k,v]) => !Array.isArray(v) || v.length !== 4);
console.log("bad:", JSON.stringify(bad).slice(0,500));
console.log("count", Object.keys(results).length);
console.log(JSON.stringify(results[failures[0].id]));

const failures = load("failures"), hist = load("hist");
const owners = {};
const news = [];
for (const f of failures) {
  const h = hist[f.id];
  const p = h.filter(x => x.conclusion === "passed").length;
  const cls = p === 4 ? "new" : p === 0 ? "persistent" : "intermittent";
  owners[f.owner] = owners[f.owner] || { owner: f.owner, new: 0, persistent: 0, intermittent: 0 };
  owners[f.owner][cls]++;
  if (cls === "new") news.push({ id: f.id, duration_ms: f.duration_ms });
}
news.sort((a,b) => b.duration_ms - a.duration_ms || (a.id < b.id ? -1 : 1));
return JSON.stringify({ total: failures.length, owners: Object.values(owners).sort((a,b)=> a.owner<b.owner?-1:1), slowest_new: news.slice(0,5) });
